def transform(grid):
    # classify isolated T tetromino components; encode by vertical band and orientation
    h,w=len(grid),len(grid[0]); seen=set(); objs=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=2 or (r,c) in seen: continue
       stack=[(r,c)]; seen.add((r,c)); cells=[]
       while stack:
        x,y=stack.pop(); cells.append((x,y))
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
         q=(x+dx,y+dy)
         if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]==2 and q not in seen: seen.add(q);stack.append(q)
       if len(cells)==4:
        minr=min(x for x,y in cells); maxr=max(x for x,y in cells)
        # stem direction: 3-cell bar on row and single cell toward top/bottom
        counts={rr:sum(x==rr for x,y in cells) for rr in range(minr,maxr+1)}
        stem= minr if counts[minr]==1 else maxr
        up = stem==minr
        cy=sum(x for x,y in cells)/4
        band=min(2,int(cy*3/h))
        objs.append((band,up))
    out=[[0]*6 for _ in range(3)]
    for band,up in objs: out[band][0 if up else 3]=3 if up else 1
    return out

